#nullable enable // autogenerated

using System;
using MVZ2.UI;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.Level.Curses
{
    public class CurseChoosingDialog : MonoBehaviour
    {
        public void UpdateCurses(CurseSelectItemViewData[] items)
        {
            curseList.updateList(items.Length, (i, obj) =>
            {
                var item = obj.GetComponent<CurseSelectItem>();
                item.UpdateItem(items[i]);
            },
            obj =>
            {
                var item = obj.GetComponent<CurseSelectItem>();
                item.OnClick += OnItemClickedCallback;
                item.OnPointerEnter += OnItemPointerEnterCallback;
                item.OnPointerExit += OnItemPointerExitCallback;
            },
            obj =>
            {
                var item = obj.GetComponent<CurseSelectItem>();
                item.OnClick -= OnItemClickedCallback;
                item.OnPointerEnter -= OnItemPointerEnterCallback;
                item.OnPointerExit -= OnItemPointerExitCallback;
            });
        }
        public CurseSelectItem? GetCurseSelectItem(int index)
        {
            return curseList.getElement<CurseSelectItem>(index);
        }
        private void Awake()
        {
            backButton.onClick.AddListener(() => OnBackButtonClick?.Invoke());
            repickButton.onClick.AddListener(() => OnRepickButtonClick?.Invoke());
            selectAllButton.onClick.AddListener(() => OnSelectAllButtonClick?.Invoke());
            deselectAllButton.onClick.AddListener(() => OnDeselectAllButtonClick?.Invoke());
            questionMark.OnPointerEnter += () => OnQuestionMarkPointerEnter?.Invoke();
            questionMark.OnPointerExit += () => OnQuestionMarkPointerExit?.Invoke();
        }
        private void OnItemClickedCallback(CurseSelectItem item)
        {
            OnItemClick?.Invoke(curseList.indexOf(item));
        }
        private void OnItemPointerEnterCallback(CurseSelectItem item)
        {
            OnItemPointerEnter?.Invoke(curseList.indexOf(item));
        }
        private void OnItemPointerExitCallback(CurseSelectItem item)
        {
            OnItemPointerExit?.Invoke(curseList.indexOf(item));
        }
        public event Action<int>? OnItemClick;
        public event Action<int>? OnItemPointerEnter;
        public event Action<int>? OnItemPointerExit;
        public event Action? OnBackButtonClick;
        public event Action? OnRepickButtonClick;
        public event Action? OnQuestionMarkPointerEnter;
        public event Action? OnQuestionMarkPointerExit;
        public event Action? OnSelectAllButtonClick;
        public event Action? OnDeselectAllButtonClick;
        public QuestionMark QuestionMark => questionMark;
        [SerializeField]
        private ElementList curseList = null!;
        [SerializeField]
        private Button backButton = null!;
        [SerializeField]
        private Button repickButton = null!;
        [SerializeField]
        private QuestionMark questionMark = null!;
        [SerializeField]
        private Button selectAllButton = null!;
        [SerializeField]
        private Button deselectAllButton = null!;
    }
}
